import{_ as l,r as s,o,c as p,e as n,a as c,s as r}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Поля контента - October CMS - 3.x","titleTemplate":false,"description":"Начните с определения полей формы для вашего контента.","frontmatter":{"subtitle":"Начните с определения полей формы для вашего контента."},"headers":[{"level":2,"title":"Свойства списка и фильтра","slug":"своиства-списка-и-фильтра","link":"#своиства-списка-и-фильтра","children":[{"level":3,"title":"Конфигурация поля","slug":"конфигурация-поля","link":"#конфигурация-поля","children":[]},{"level":3,"title":"Внешняя конфигурация","slug":"внешняя-конфигурация","link":"#внешняя-конфигурация","children":[]}]},{"level":2,"title":"Валидация полей формы","slug":"валидация-полеи-формы","link":"#валидация-полеи-формы","children":[]},{"level":2,"title":"Модификация основных полей","slug":"модификация-основных-полеи","link":"#модификация-основных-полеи","children":[{"level":4,"title":"См. также","slug":"см-также","link":"#см-также","children":[]}]}],"relativePath":"3.x/ru/cms/tailor/content-fields.md","filePath":"3.x/ru/cms/tailor/content-fields.md"}'),d={name:"3.x/ru/cms/tailor/content-fields.md"};function u(i,a,k,m,g,y){const e=s("pre-heading"),t=s("post-heading");return o(),p("div",null,[n(e),a[0]||(a[0]=c("h1",null,"Поля контента",-1)),n(t),a[1]||(a[1]=r(`<div class="custom-block aside"><p>Вы можете создавать пользовательские поля контента, <a href="./../../extend/tailor-fields.html">расширяя Tailor</a>.</p></div><p>Поля контента — это основа модуля Tailor, определяющая способ настройки и отображения полей. Эти определения обычно находятся в свойстве <strong>fields</strong> чертежа.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">name</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Full Name
        <span class="token key atrule">type</span><span class="token punctuation">:</span> text
</code></pre></div><div class="custom-block tip"><p>Полный список доступных полей можно найти в <a href="./../../element/form-fields.html">разделе элементов панели управления</a>.</p></div><p>Для каждого поля можно указать следующие общие свойства, где применимо.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>имя, отображаемое при показе поля формы пользователю.</td></tr><tr><td><strong>shortLabel</strong></td><td>более короткая метка для использования в списках и фильтрах.</td></tr><tr><td><strong>type</strong></td><td>определяет способ отображения поля, см. <a href="./../../element/form-fields.html">определения полей формы</a>. По умолчанию: text.</td></tr><tr><td><strong>span</strong></td><td>выравнивает поле формы по одной стороне. Варианты: auto, left, right, row, full, adaptive. По умолчанию: <code>full</code>.</td></tr><tr><td><strong>spanClass</strong></td><td>используется с параметром span <code>row</code> для отображения формы в виде сетки Bootstrap, например, <code>spanClass: col-4</code>.</td></tr><tr><td><strong>size</strong></td><td>указывает размер поля для полей, поддерживающих это свойство, например, поле textarea.</td></tr><tr><td><strong>placeholder</strong></td><td>если поле поддерживает значение-заполнитель.</td></tr><tr><td><strong>comment</strong></td><td>размещает описательный комментарий под полем.</td></tr><tr><td><strong>commentAbove</strong></td><td>размещает комментарий над полем.</td></tr><tr><td><strong>commentHtml</strong></td><td>разрешает HTML-разметку внутри комментария. По умолчанию: <code>false</code>.</td></tr><tr><td><strong>default</strong></td><td>указывает значение по умолчанию для поля. Для виджетов <code>dropdown</code>, <code>checkboxlist</code>, <code>radio</code> и <code>balloon-selector</code> можно указать ключ варианта для выбора по умолчанию.</td></tr><tr><td><strong>tab</strong></td><td>назначает поле на вкладку.</td></tr><tr><td><strong>validation</strong></td><td>определяет правила валидации для поля формы, см. <a href="./../../extend/services/validation.html">статью о валидации</a> для определений правил.</td></tr><tr><td><strong>trigger</strong></td><td>указывает условия для этого поля с помощью <a href="./../../element/form-fields.html">событий триггера</a>.</td></tr><tr><td><strong>preset</strong></td><td>позволяет устанавливать начальное значение поля на основе значения другого поля, преобразованного с помощью <a href="./../../element/form-fields.html">конвертера предустановок ввода</a>.</td></tr><tr><td><strong>translatable</strong></td><td>отключает перевод для этого поля при использовании <code>multisite</code> в определении чертежа.</td></tr></tbody></table></div><h2 id="своиства-списка-и-фильтра"><a href="#своиства-списка-и-фильтра" class="header-anchor">#</a> Свойства списка и фильтра</h2><p>Что касается отображения поля в списке или фильтре, каждое поле имеет собственные настройки по умолчанию. Вы можете переопределить эти настройки для каждого поля, что подходит для незначительных изменений. Для более сложных случаев рекомендуется определять столбцы и фильтры отдельно от полей (см. ниже).</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>column</strong></td><td>определяет способ отображения поля в списке, см. <a href="./../../element/list-columns.html">определения столбцов списка</a>.</td></tr><tr><td><strong>scope</strong></td><td>определяет способ отображения поля в фильтре, см. <a href="./../../element/filter-scopes.html">определения фильтров</a>.</td></tr></tbody></table></div><h3 id="конфигурация-поля"><a href="#конфигурация-поля" class="header-anchor">#</a> Конфигурация поля</h3><p>Примером может быть указание различных меток с помощью свойств <code>column</code> или <code>scope</code> поля.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">myfield</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Form Label
    <span class="token key atrule">column</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> List Label
    <span class="token key atrule">scope</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Filter Label
</code></pre></div><p>Если установлено значение <code>false</code>, поле будет отключено и не отображается.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">myfield</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Form Label
    <span class="token key atrule">column</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
    <span class="token key atrule">scope</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
</code></pre></div><p>Тип <code>column</code> может быть установлен в <code>invisible</code>, чтобы сделать его скрытым из списка по умолчанию.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">myfield</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Form Label
    <span class="token key atrule">column</span><span class="token punctuation">:</span> invisible
</code></pre></div><h3 id="внешняя-конфигурация"><a href="#внешняя-конфигурация" class="header-anchor">#</a> Внешняя конфигурация</h3><p>Вы можете определить фильтры и столбцы отдельно от полей формы, используя свойства <code>columns</code> и <code>scopes</code> в чертеже. При использовании внешней конфигурации представление по умолчанию будет заменено только определёнными полями.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">scopes</span><span class="token punctuation">:</span>
    <span class="token key atrule">myfield</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Filter Label
        <span class="token comment"># [...]</span>

<span class="token key atrule">columns</span><span class="token punctuation">:</span>
    <span class="token key atrule">myfield</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> List Label
        <span class="token comment"># [...]</span>

<span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">myfield</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Form Label
        <span class="token comment"># [...]</span>
</code></pre></div><div class="custom-block tip"><p>Определение <strong>fields</strong> должно существовать для того, чтобы определение <strong>columns</strong> или <strong>scopes</strong> было допустимым. Чтобы скрыть определение из формы, используйте <code>hidden: true</code>, а затем <code>hidden: false</code> для отображения в столбце или фильтре.</p></div><p>Столбцы списка имеют сокращённые значения. Передача строки заменит метку, передача <code>true</code> включит столбец по умолчанию, передача <code>false</code> удалит столбец, а передача <code>invisible</code> сделает столбец невидимым.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">columns</span><span class="token punctuation">:</span>
    <span class="token key atrule">myfield</span><span class="token punctuation">:</span> List Label   <span class="token comment"># New Label</span>
    <span class="token key atrule">myfield</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>         <span class="token comment"># Shown</span>
    <span class="token key atrule">myfield</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>        <span class="token comment"># Hidden</span>
    <span class="token key atrule">myfield</span><span class="token punctuation">:</span> invisible    <span class="token comment"># Invisible</span>
    <span class="token key atrule">myfield</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token punctuation">...</span><span class="token punctuation">]</span>        <span class="token comment"># Config Array</span>
</code></pre></div><p>Фильтры имеют аналогичные сокращённые значения.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">scopes</span><span class="token punctuation">:</span>
    <span class="token key atrule">myfield</span><span class="token punctuation">:</span> Filter Label <span class="token comment"># New Label</span>
    <span class="token key atrule">myfield</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>         <span class="token comment"># Shown</span>
    <span class="token key atrule">myfield</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>        <span class="token comment"># Hidden</span>
    <span class="token key atrule">myfield</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token punctuation">...</span><span class="token punctuation">]</span>        <span class="token comment"># Config Array</span>
</code></pre></div><h2 id="валидация-полеи-формы"><a href="#валидация-полеи-формы" class="header-anchor">#</a> Валидация полей формы</h2><p>Вы можете указать правила валидации для полей формы с помощью свойства <code>validation</code>, см. <a href="./../../extend/services/validation.html">статью о валидации</a> для определений правил.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">myfield</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Featured Text
        <span class="token key atrule">validation</span><span class="token punctuation">:</span> <span class="token string">&quot;required|min:15&quot;</span>
</code></pre></div><p>Правила валидации также можно определить внешне в файле чертежа с помощью свойства <code>validation</code> чертежа. Это позволяет устанавливать пользовательские имена атрибутов и сообщения валидации.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">validation</span><span class="token punctuation">:</span>
    <span class="token key atrule">rules</span><span class="token punctuation">:</span>
        <span class="token key atrule">myfield</span><span class="token punctuation">:</span> <span class="token string">&quot;required|min:15&quot;</span>
    <span class="token key atrule">attributeNames</span><span class="token punctuation">:</span>
        <span class="token key atrule">myfield</span><span class="token punctuation">:</span> My Field
    <span class="token key atrule">customMessages</span><span class="token punctuation">:</span>
        <span class="token key atrule">myfield.min</span><span class="token punctuation">:</span> <span class="token string">&quot;My field has to be at least 15 characters long&quot;</span>

<span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">myfield</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Form Label
        <span class="token comment"># [...]</span>
</code></pre></div><p>Правило валидации <code>unique</code> настраивается автоматически и не требует указания имени таблицы.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">unique_field</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Unique Field
    <span class="token key atrule">validation</span><span class="token punctuation">:</span> unique
</code></pre></div><p>Правило валидации <code>required</code> поддерживает модификаторы <strong>create</strong> и <strong>update</strong> для применения только при создании или обновлении модели соответственно. Следующее правило обязательно только при создании новой записи.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">password</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Password
    <span class="token key atrule">validation</span><span class="token punctuation">:</span> <span class="token string">&quot;required:create&quot;</span>
</code></pre></div><h2 id="модификация-основных-полеи"><a href="#модификация-основных-полеи" class="header-anchor">#</a> Модификация основных полей</h2><p>Каждая запись чертежа имеет несколько основных полей, <a href="./models.html">определённых атрибутами модели</a>. Вы можете изменить эти поля при определённых условиях.</p><p>Запись Entry включена по умолчанию, однако вы можете изменить это, указав новое значение по умолчанию для поля <code>is_enabled</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">is_enabled</span><span class="token punctuation">:</span>
        <span class="token key atrule">default</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
</code></pre></div><p>Заполнитель поля <code>title</code> генерируется на основе имени чертежа, однако вы можете настроить его для более полезного описания в зависимости от случая. Например, <em>Имя и Фамилия</em>, <em>Название мероприятия</em> или <em>Название места</em>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span>
        <span class="token key atrule">placeholder</span><span class="token punctuation">:</span> Event Title
</code></pre></div><p>В некоторых случаях поле <code>title</code> может быть не обязательным, например, при использовании <a href="./blueprints.html">единичного чертежа</a>. Вы можете установить свойство <code>hidden</code> в <code>true</code>. Скрытие заголовка отключит встроенную валидацию для этого поля.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">title</span><span class="token punctuation">:</span>
        <span class="token key atrule">hidden</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><h4 id="см-также"><a href="#см-также" class="header-anchor">#</a> См. также</h4><div class="custom-block also"><ul><li><a href="./../../element/form-fields.html">Определение полей формы</a></li><li><a href="./../../extend/tailor-fields.html">Создание полей Tailor</a></li></ul></div>`,43))])}const b=l(d,[["render",u]]);export{f as __pageData,b as default};
